(212, 3, '2', 'Twista can rap 1000 words 300 seconds faster than Busta Rhymes.<br>\n		Together it takes them 143s. How long does it take Twista to rap 1000 words? <br>\n		(Amount<sub>1</sub>/time<sub>1</sub>)+(Amount<sub>2</sub>/time<sub>2</sub>)=(Amount<sub>together</sub>', '', '200', '300', '250', '150', '', '', '', '', 1),
