(1173, 83, '3', 'An UberX drive costs a $2.20 flat rate plus $0.26 per minute plus $0.81 a km. \n		<br>You get a ride home from the movies and your ride costs $12. The drive took 5 minutes. \n		<br>What is the distance between your house and the movie theater?\n		<br>Hint: To', '', '10.5km', '12km', '10.5m', '14.5km', '', '', '', '', 1),
