(1179, 1001, '3', 'On Jan 4th 2010 you invested $1000 into Apple and Amazon. Two years later, you check the stock prices. Apple is up from 30.57 to 59.06 (93%) and Amazon is up from 133.90 to 177.51 (32%). \n	<br>Your stocks are currently worth $1600.12 (nice!) and you rememb', '', 'Apple: 492 Amazon: 508', 'Apple: 482 Amazon: 518', 'Apple: 508 Amazon: 492', 'Apple: 502 Amazon: 498', '', '', '', '', 1),
