(1183, 87, '2', 'Write an equivalent equation to y=4x-3. <br>\n   Hint: Equivalent euqations have the same slope and y-int. <br>\n   An equivalent equation can be derived from multiplying (or dividing) the coefficients (numbers beside the variables) numbers by a common numbe', '', '2y=12x-6', '4y=8x-36', '2y=8x-6', '2y=2x-6', '', '', '', '', 3),
(1184, 87, '1', 'Write an equivalent equation to y=4x-3. <br>\n   Hint: Equivalent euqations have the same slope and y-int. <br> \n   An equivalent equation can be derived from multiplying the coefficients (beside the variables) numbers by a common digit.<br>\n   For example,', '', '2y=2x-6', '2y=12x-6', '4y=8x-36', '2y=8x-6', '', '', '', '', 4),
