(1187, 1001, '3', 'On Jan 4th 2010 you invested $1000 into Apple and Amazon. Two years later, you check the stock prices. Apple is up from 30.57 to 59.06 (93%) and Amazon is up from 133.90 to 177.51 (32%). \n	<br>Your stocks are currently worth $1567.18 (nice!) and you rememb', '', 'Apple: 562 Amazon: 438', 'Apple: 448 Amazon: 552', 'Apple: 428 Amazon: 572', 'Apple: 438 Amazon: 562', '', '', '', '', 4),
(1188, 46, '2', 'Find the point on the line y=-3x+5 when x=1. Which quadrant is the point in?<br>\n  Hint: To solve this, sub 1 into the equation of y= -3x + 5 as x and solve.<br>\n  Remember, the quadrants are numbered in counterclockwise direction', '', '(3,-1) Quadrant 2', '(1,2) Quadrant 1', '(0,1) Quadrant 4', '(5,-3) Quadrant 3', '', '', '', '', 2),
