(1190, -1, '2', '', '', '', '', '', '', '', '', '', '', 0),
(1191, 103, '2', 'Is the point (1,1) inside the circle:\n		<br>x^2+y^2 = 3?\n		<br>Remember, the given equation is for a circle located at the origin.\n		<br>To determine the point\'s location, substitute your x and y values in the equation.', '', 'Impossible to tell', 'At the origin', 'Outside the circle', 'Inside the circle', '', '', '', '', 4),
